'use strict';
const C=OpticalCodec,$=id=>document.getElementById(id),ctx=$('sendCanvas').getContext('2d'),rx=$('receiveCanvas').getContext('2d',{willReadFrequently:true});
let tx=null,timer=null,stream=null,scanTimer=null,imageData=null,crop=null,drag=null,session=null,url=null,revision=0,finishing=false;
const hex=a=>Array.from(a,x=>x.toString(16).padStart(2,'0')).join('');
async function sha(bytes){return hex(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)))}
function stats(){const n=+$('density').value,b=+$('colors').value,fps=Math.min(20,Math.max(1,+$('fps').value||5)),cap=C.capacity(n,b);$('fps').value=fps;$('sendStats').textContent=`${cap.toLocaleString()} bytes / フレーム（訂正・ヘッダー込み）\n理論値 ${(cap*fps/1024).toFixed(1)} KiB/s · 2 MiB ≈ ${Math.ceil(2*1024*1024/cap/fps)} 秒（再送・撮影ロスを除く）`;return {n,b,fps,cap}}
function pause(){clearInterval(timer);timer=null;$('play').textContent='送信を開始'}
function draw(){if(!tx)return;const start=tx.index*tx.cap,data=tx.bytes.subarray(start,start+tx.cap),a=C.packet(data,tx.id,tx.index,tx.count,tx.n,tx.b),r=C.raster(C.cells(a,tx.n,tx.b),tx.n,tx.b,3);$('sendCanvas').width=r.width;$('sendCanvas').height=r.height;ctx.putImageData(new ImageData(r.data,r.width,r.height),0,0);$('sendStatus').textContent=`${tx.name} · ${tx.size.toLocaleString()} bytes\nフレーム ${tx.index+1} / ${tx.count} · ID ${hex(tx.id)}`}
async function prepare(file){pause();const token=++revision;tx=null;for(const id of ['play','prev','next','png','loopback'])$(id).disabled=true;if(file.size>32*1024*1024)throw Error('ファイルは32 MiBまでです');$('sendStatus').textContent='ファイルを符号化しています…';const data=new Uint8Array(await file.arrayBuffer()),hash=await sha(data),meta=new TextEncoder().encode(JSON.stringify({name:file.name,size:data.length,sha256:hash}));if(meta.length>65535)throw Error('ファイル名が長すぎます');const bytes=new Uint8Array(2+meta.length+data.length);new DataView(bytes.buffer).setUint16(0,meta.length,true);bytes.set(meta,2);bytes.set(data,2+meta.length);const conf=stats();if(token!==revision)return;tx={...conf,bytes,id:crypto.getRandomValues(new Uint8Array(8)),count:Math.ceil(bytes.length/conf.cap),index:0,name:file.name,size:file.size,file};for(const id of ['play','prev','next','png','loopback'])$(id).disabled=false;draw()}
function error(e,target='receiveStatus'){$(target).textContent=e.message||String(e)}
$('source').onchange=()=>{if($('source').files[0])prepare($('source').files[0]).catch(e=>error(e,'sendStatus'))};
for(const id of ['density','colors'])$(id).onchange=()=>{stats();if(tx)prepare(tx.file).catch(e=>error(e,'sendStatus'))};$('fps').onchange=()=>{stats();pause()};
$('play').onclick=()=>{if(timer){pause();return}if(!tx)return;draw();timer=setInterval(()=>{tx.index=(tx.index+1)%tx.count;draw()},1000/stats().fps);$('play').textContent='一時停止'};
for(const [id,step] of [['prev',-1],['next',1]])$(id).onclick=()=>{pause();tx.index=(tx.index+step+tx.count)%tx.count;draw()};
$('fullscreen').onclick=()=>{$('sendStage').requestFullscreen().catch(e=>error(e,'sendStatus'))};
function save(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
$('png').onclick=()=>{$('sendCanvas').toBlob(b=>save(b,`optical-${hex(tx.id)}-${String(tx.index+1).padStart(5,'0')}.png`))};
$('demo').onclick=()=>{const data=new Uint8Array(128*1024);for(let i=0;i<data.length;i++)data[i]=(i*37+(i>>8))&255;prepare(new File([data],'demo-128KiB.bin')).catch(e=>error(e,'sendStatus'))};
function reset(){session=null;finishing=false;if(url)URL.revokeObjectURL(url);url=null;$('download').hidden=true;$('progress').value=0;$('receiveStats').textContent='0 / 0 フレーム';$('receiveStatus').textContent='受信データをリセットしました。'}
$('reset').onclick=reset;
async function accept(frame){if(!session)session={id:frame.id,count:frame.count,n:frame.n,b:frame.b,parts:new Map(),bytes:0,fixed:0,complete:false};const s=session;if(frame.id!==s.id){$('receiveStatus').textContent='別の転送IDを検出しました。新しいファイルを受け取るにはリセットしてください。';return}if(frame.count!==s.count||frame.n!==s.n||frame.b!==s.b)throw Error('同じIDで設定が一致しません');if(s.parts.has(frame.index))return;if(s.bytes+frame.data.length>C.MAX)throw Error('受信サイズ上限を超えました');s.parts.set(frame.index,frame.data);s.bytes+=frame.data.length;s.fixed+=frame.fixed;$('progress').value=s.parts.size/s.count;$('receiveStats').textContent=`${s.parts.size} / ${s.count} フレーム · ${(s.bytes/1024).toFixed(1)} KiB\n訂正したビット: ${s.fixed} · ID ${s.id}`;$('receiveStatus').textContent='フレームを受信しています。抜けたフレームは次の周回で補います。';if(s.parts.size!==s.count||finishing||s.complete)return;finishing=true;try{const bytes=new Uint8Array(s.bytes);let offset=0;for(let i=0;i<s.count;i++){bytes.set(s.parts.get(i),offset);offset+=s.parts.get(i).length}const mlen=new DataView(bytes.buffer).getUint16(0,true);if(mlen>bytes.length-2)throw Error('メタデータ長不正');const meta=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes.subarray(2,mlen+2))),data=bytes.slice(mlen+2);if(typeof meta.name!=='string'||meta.size!==data.length||typeof meta.sha256!=='string')throw Error('ファイル情報不正');if(await sha(data)!==meta.sha256)throw Error('SHA-256不一致：復元内容が一致しません');if(session!==s)return;url=URL.createObjectURL(new Blob([data]));$('download').href=url;$('download').download=meta.name.replace(/[\\/\x00-\x1f]/g,'_');$('download').textContent=`${meta.name} を保存`; $('download').hidden=false;$('receiveStatus').textContent=`復元完了 · ${data.length.toLocaleString()} bytes · SHA-256一致`;s.complete=true;stop()}finally{if(session===s)finishing=false}}
function showImage(img){imageData=img;$('receiveCanvas').width=img.width;$('receiveCanvas').height=img.height;rx.putImageData(img,0,0);if(crop){rx.strokeStyle='#65ff76';rx.lineWidth=Math.max(2,img.width/300);rx.strokeRect(crop.x,crop.y,crop.w,crop.h)}}
async function readImage(img){showImage(img);await accept(C.decode(img,crop))}
$('images').onchange=async()=>{for(const file of $('images').files){try{const bitmap=await createImageBitmap(file);const c=document.createElement('canvas');c.width=bitmap.width;c.height=bitmap.height;c.getContext('2d').drawImage(bitmap,0,0);bitmap.close();await readImage(c.getContext('2d').getImageData(0,0,c.width,c.height))}catch(e){error(e)}}};
function stop(){clearInterval(scanTimer);scanTimer=null;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('video').srcObject=null;$('stop').disabled=true;$('camera').disabled=false;$('screen').disabled=false}
$('stop').onclick=()=>{stop();$('receiveStatus').textContent='読み取りを停止しました。受信済みフレームは保持しています。'};
async function capture(camera){stop();crop=null;if(!navigator.mediaDevices)throw Error('localhost またはHTTPSで開いてください');stream=await (camera?navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}}}):navigator.mediaDevices.getDisplayMedia({video:{frameRate:{ideal:30}},audio:false}));const video=$('video');video.srcObject=stream;stream.getVideoTracks()[0].onended=()=>stop();await video.play();$('stop').disabled=false;$('camera').disabled=true;$('screen').disabled=true;$('receiveStatus').textContent='映像を読み取り中…';let busy=false;scanTimer=setInterval(async()=>{if(busy||!video.videoWidth)return;busy=true;try{const c=document.createElement('canvas');c.width=video.videoWidth;c.height=video.videoHeight;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(video,0,0);await readImage(x.getImageData(0,0,c.width,c.height))}catch(e){if(!session?.complete)error(e)}finally{busy=false}},100)}
$('camera').onclick=()=>capture(true).catch(error);$('screen').onclick=()=>capture(false).catch(error);
function point(e){const r=$('receiveCanvas').getBoundingClientRect();return {x:Math.max(0,Math.min($('receiveCanvas').width,(e.clientX-r.left)*$('receiveCanvas').width/r.width)),y:Math.max(0,Math.min($('receiveCanvas').height,(e.clientY-r.top)*$('receiveCanvas').height/r.height))}}
$('receiveCanvas').onpointerdown=e=>{if(!imageData)return;drag=point(e);$('receiveCanvas').setPointerCapture(e.pointerId)};
$('receiveCanvas').onpointerup=async e=>{if(!drag||!imageData)return;const end=point(e);crop={x:Math.min(drag.x,end.x),y:Math.min(drag.y,end.y),w:Math.abs(end.x-drag.x),h:Math.abs(end.y-drag.y)};drag=null;if(crop.w<50||crop.h<50){crop=null;return}try{await readImage(imageData)}catch(e){error(e)}};
$('autoCrop').onclick=async()=>{crop=null;if(imageData)try{await readImage(imageData)}catch(e){error(e)}};
$('loopback').onclick=async()=>{if(!tx)return;pause();stop();reset();crop=null;$('loopback').disabled=true;const t=tx,old=t.index;try{for(let i=t.count-1;i>=0;i--){if(tx!==t)throw Error('送信設定が変更されました');t.index=i;draw();await readImage(ctx.getImageData(0,0,$('sendCanvas').width,$('sendCanvas').height));if(i%4===0)await new Promise(r=>setTimeout(r,0))}$('sendStatus').textContent='自己テスト成功：画像の画素から逆順受信し、SHA-256が一致しました。'}catch(e){error(e,'sendStatus')}finally{t.index=old;$('loopback').disabled=!tx}};
stats();
